#[test]
fn every_jar_member_of_the_converted_classes_is_accounted_for() {
    let mut want: Vec<String> = rows("API24")
        .iter()
        .map(|r| format!("{}\t{}\t{}\t{}", r[1], r[2], r[3], r[4]))
        .collect();
    let mut have: Vec<String> = MEMBERS
        .iter()
        .map(|m| format!("{}\t{}\t{}\t{}", m.0, m.1, m.2, m.3))
        .collect();
    want.sort();
    have.sort();
    assert_eq!(have, want, "MEMBERS and the jar disagree");
    for m in MEMBERS {
        assert!(
            m.4.starts_with("ported: ")
                || m.4.starts_with("NOT PORTED: ")
                || m.4.starts_with("NOT APPLICABLE: "),
            "member without a disposition: {m:?}"
        );
    }
    let sup: Vec<(String, String, String)> = rows("API24SUP")
        .iter()
        .map(|r| (r[1].to_string(), r[2].to_string(), r[3].to_string()))
        .collect();
    let have_sup: Vec<(String, String, String)> = SUPERS
        .iter()
        .map(|s| (s.0.to_string(), s.1.to_string(), s.2.to_string()))
        .collect();
    assert_eq!(have_sup, sup);
}

#[test]
fn the_not_ported_members_are_the_identity_hash_ones() {
    let not_ported: Vec<String> = MEMBERS
        .iter()
        .filter(|m| m.4.starts_with("NOT PORTED"))
        .map(|m| format!("{}.{}", m.0, m.2))
        .collect();
    assert_eq!(
        not_ported,
        [
            "Frame.hashCode()int",
            "Frame.toString()java.lang.String",
            "VertexFormatElement.hashCode()int",
            "BlendFunction.hashCode()int",
            "BindGroupLayout$UniformDescription.hashCode()int",
            "StrictQueue$RunnableWithPriority.equals(java.lang.Object)boolean",
            "StrictQueue$RunnableWithPriority.hashCode()int",
            "StrictQueue$RunnableWithPriority.toString()java.lang.String",
            "ColorTargetState.hashCode()int",
            "DeviceInfo.hashCode()int",
        ]
    );
}
